-- A fresh namespace. Never reads or migrates the previous platform's tables.
create table if not exists gather_people (id text primary key, clerk_id text unique, phone text unique, name text not null, email text, timezone text not null default 'America/New_York', created_at bigint not null);
create table if not exists gather_agents (id text primary key, owner_id text references gather_people(id), name text not null, purpose text not null, instructions text not null default '', created_at bigint not null);
create table if not exists gather_spaces (id text primary key, owner_id text references gather_people(id), agent_id text references gather_agents(id), name text not null, kind text not null check(kind in ('private','family','friends','neighborhood')), channel text not null default 'web', external_id text unique, instructions text not null default '', audience_version integer not null default 1, created_at bigint not null);
create table if not exists gather_members (space_id text references gather_spaces(id) on delete cascade, person_id text references gather_people(id), role text not null default 'member', joined_at bigint not null, primary key(space_id,person_id));
create table if not exists gather_messages (id text primary key, space_id text references gather_spaces(id), person_id text references gather_people(id), role text not null, text text not null, external_id text unique, run_id text, created_at bigint not null);
create table if not exists gather_memories (id text primary key, agent_id text references gather_agents(id), owner_id text references gather_people(id), space_id text references gather_spaces(id), kind text not null, text text not null, aliases jsonb not null default '[]', source_message_id text, revision integer not null default 1, observed_at bigint not null, updated_at bigint not null, expires_at bigint, check((owner_id is not null and space_id is null) or (owner_id is null and space_id is not null)));
create index if not exists gather_memory_search on gather_memories using gin(to_tsvector('simple',text));
create table if not exists gather_memory_history (id bigserial primary key, memory_id text references gather_memories(id) on delete cascade, text text not null, revision integer not null, changed_at bigint not null);
create table if not exists gather_profiles (agent_id text references gather_agents(id), owner_id text references gather_people(id), text text not null, revision_digest text not null, updated_at bigint not null, primary key(agent_id,owner_id));
create table if not exists gather_runs (id text primary key, space_id text references gather_spaces(id), requester_id text references gather_people(id), request text not null, status text not null default 'queued', transcript jsonb not null default '[]', pending_calls jsonb not null default '[]', plan jsonb, reply text, private_result_owner text, audience_version integer not null, tier text not null default 'cheap', cost_usd double precision not null default 0, lease_until bigint not null default 0, created_at bigint not null, updated_at bigint not null);
create table if not exists gather_events (seq bigserial primary key, space_id text references gather_spaces(id), run_id text references gather_runs(id), type text not null, payload jsonb not null default '{}', created_at bigint not null);
create table if not exists gather_executions (id text primary key, run_id text references gather_runs(id), step_id text, tool text not null, input jsonb not null, fingerprint text unique not null, status text not null, output jsonb, provider_ref text, verified boolean not null default false, simulated boolean not null default false, created_at bigint not null, updated_at bigint not null);
create table if not exists gather_approvals (id text primary key, run_id text references gather_runs(id), approver_id text references gather_people(id), kind text not null, fingerprint text not null, summary text not null, preview text not null, audience_version integer, status text not null default 'pending', expires_at bigint not null, created_at bigint not null, unique(run_id, fingerprint, kind));
create table if not exists gather_tasks (id text primary key, space_id text references gather_spaces(id), created_by text references gather_people(id), assignee_id text references gather_people(id), title text not null, category text not null default 'coordination', status text not null default 'proposed', due_at bigint, followup_at bigint, notified_at bigint, note text not null default '', candidates jsonb not null default '[]', created_at bigint not null, updated_at bigint not null);
create table if not exists gather_jobs (id text primary key, space_id text references gather_spaces(id), requester_id text references gather_people(id), task_id text references gather_tasks(id), prompt text not null, kind text not null default 'task', next_at bigint not null, interval_ms bigint, status text not null default 'scheduled', lease_until bigint not null default 0, attempts integer not null default 0, last_run_id text, created_at bigint not null);
create table if not exists gather_connections (id text primary key, owner_id text references gather_people(id), kind text not null, name text not null, secret text, config jsonb not null default '{}', status text not null default 'active', unique(owner_id,kind,name));
create table if not exists gather_links (token_hash text primary key, owner_id text references gather_people(id), purpose text not null, state jsonb not null, expires_at bigint not null);
create table if not exists gather_usage (id bigserial primary key, run_id text, kind text not null, cost_usd double precision not null default 0, created_at bigint not null);
create table if not exists gather_outbox (id text primary key, space_id text references gather_spaces(id), message_id text references gather_messages(id), text text not null, status text not null default 'queued', lease_until bigint not null default 0, attempts integer not null default 0, provider_ref text, created_at bigint not null);
create index if not exists gather_runs_work on gather_runs(status,lease_until);
create index if not exists gather_jobs_due on gather_jobs(status,next_at);
create index if not exists gather_events_space on gather_events(space_id,seq);
create table if not exists gather_files(id text primary key,owner_id text references gather_people(id),space_id text references gather_spaces(id),name text not null,mime text not null,size integer not null,text text not null,created_at bigint not null);
alter table gather_outbox add column if not exists audience_version integer;
